/*saveBuyerMdCmCartQtyPunchOut*/

UPDATE DOOSCART  SET CART_QTY = #{CART_QTY}                 
WHERE BUYER     = #{BUYER}                              
	AND USER_ID      = #{USER_ID}                              
	AND USE_FLAG  = #{USE_FLAG}                            
	AND BUYER_ITEM_NO  = #{BUYER_ITEM_NO}                    
	AND CONTRACT_NO  = #{CONTRACT_NO}                        
	AND CONTRACT_SEQ  = #{CONTRACT_SEQ}
	AND AGENT  = #{AGENT}                    
	AND BYIT_COMORG_CODE  = #{BYIT_COMORG_CODE}
	AND ITEM_SEQ  = #{ITEM_SEQ}



		/*deleteBuyerMdCmCartListPunchOut*/
             UPDATE DOOSCART SET                  
                USE_FLAG = 'T',                   
                REG_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                REG_TIME = SUBSTR(TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS'),10,6), 
                SEQ = (SELECT DECODE(MAX(SEQ),NULL,'0', MAX(SEQ))+1   
	         FROM DOOSCART                  
	        WHERE BUYER         =#{BUYER}            
	          AND USER_ID       =#{USER_ID}   
	          AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
	          AND CONTRACT_NO   = #{CONTRACT_NO}
	          AND CONTRACT_SEQ  = #{CONTRACT_SEQ}   
	          AND USE_FLAG      = 'T' ),     
	      ITEM_SEQ = (SELECT TO_CHAR(DECODE(MAX(ITEM_SEQ),NULL,'0', MAX(ITEM_SEQ))+1,'FM000000')   
	         FROM DOOSCART                  
	        WHERE BUYER         = #{BUYER}       
	          AND USER_ID       = #{USER_ID}      
	          AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}        
	          AND CONTRACT_NO   =  #{CONTRACT_NO}        
	          AND CONTRACT_SEQ  = #{CONTRACT_SEQ}       
	          AND USE_FLAG      = 'T' )      
              WHERE BUYER             = #{BUYER}       
                AND USER_ID           = #{USER_ID}        
                AND USE_FLAG          = #{USE_FLAG}      
                AND BUYER_ITEM_NO     = #{BUYER_ITEM_NO}        
                AND CONTRACT_NO       = #{CONTRACT_NO}        
                AND CONTRACT_SEQ      = #{CONTRACT_SEQ}       
                AND AGENT             = #{AGENT}      
                AND BYIT_COMORG_CODE  = #{BYIT_COMORG_CODE}           
                AND ITEM_SEQ          =  #{ITEM_SEQ}
